/**
 * Build the browser-half bundle.
 *
 * The dsh web client does not `import()` plugin client entries. It loads a
 * single file that self-registers with the boot module loader:
 *
 *   window.__ModuleLoader__.load({ id, factory: (require) => module.exports })
 *
 * and reads `name` / `inject` / `apply` off `module.exports`. So the compiled
 * modules are wrapped into one factory here — no bundler dependency, and the
 * wrapper is small enough to audit. The supported subset is deliberately narrow
 * and checked: relative requirements are inlined, anything else goes to the
 * host loader's `require`.
 *
 * Order: tsc (CommonJS, `.build/client`) -> inline `style.css` -> emit
 * `dist/client/index.js`.
 */
import { execFileSync } from 'node:child_process'
import { createRequire } from 'node:module'
import { existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, posix, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const requireFromHere = createRequire(import.meta.url)
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const buildDir = join(root, '.build', 'client')
const entry = join(buildDir, 'index.js')
const outFile = join(root, 'dist', 'client', 'index.js')
const cssFile = join(root, 'src', 'client', 'style.css')
const PLACEHOLDER = '__RETRO_CSS__'

const packageJson = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const bundleId = packageJson.name

const toId = (absolute) => relative(buildDir, absolute).split(sep).join(posix.sep)

/** Resolve a relative requirement the way Node's classic resolution would. */
function resolveLocal(fromDir, spec) {
  const base = resolve(fromDir, spec)
  for (const candidate of [base, `${base}.js`, join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate
  }
  throw new Error(`cannot resolve "${spec}" from ${toId(fromDir)}`)
}

// 1) compile -----------------------------------------------------------------
rmSync(buildDir, { recursive: true, force: true })
const tsc = requireFromHere.resolve('typescript/bin/tsc')
execFileSync(process.execPath, [tsc, '-p', join(root, 'tsconfig.client.json')], {
  cwd: root,
  stdio: 'inherit',
})

// Node must treat the compiled `.js` files as CommonJS when the tests require
// them directly; the package itself is `"type": "module"`.
writeFileSync(join(buildDir, 'package.json'), '{"type":"commonjs"}\n', 'utf8')

if (!existsSync(entry)) throw new Error(`client build produced no ${toId(entry)}`)

// 2) collect every module reachable from the entry ---------------------------
const modules = new Map() // id -> transformed CommonJS source
const queue = [entry]
while (queue.length > 0) {
  const file = queue.shift()
  const id = toId(file)
  if (modules.has(id)) continue

  const source = readFileSync(file, 'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm, '')
  const dir = dirname(file)

  // Rewrite relative requirements to bundle-local ids; leave package ids to the
  // host loader.
  modules.set(
    id,
    source.replace(/\brequire\(\s*(['"])([^'"]+)\1\s*\)/g, (match, _quote, spec) => {
      if (!spec.startsWith('.')) return match
      const target = resolveLocal(dir, spec)
      queue.push(target)
      return `__require(${JSON.stringify(toId(target))})`
    }),
  )
}

// 3) inline the stylesheet ---------------------------------------------------
const css = readFileSync(cssFile, 'utf8')
const cssLiteral = JSON.stringify(css)
let inlined = 0
for (const [id, source] of modules) {
  if (!source.includes(PLACEHOLDER)) continue
  // The placeholder is a string literal in the compiled output, and tsc keeps
  // the source's quote style — accept either form rather than guessing.
  let replaced = source
  for (const quoted of [`'${PLACEHOLDER}'`, `"${PLACEHOLDER}"`]) {
    if (!replaced.includes(quoted)) continue
    replaced = replaced.replace(quoted, () => cssLiteral)
    inlined += 1
  }
  if (replaced.includes(PLACEHOLDER)) {
    throw new Error(`${id} still contains the ${PLACEHOLDER} placeholder after inlining`)
  }
  modules.set(id, replaced)
}
if (inlined === 0) {
  throw new Error(`no module referenced the ${PLACEHOLDER} placeholder — the stylesheet would never ship`)
}

// 4) emit the factory bundle -------------------------------------------------
const indent = (text) =>
  text
    .split('\n')
    .map((line) => (line.length === 0 ? line : `        ${line}`))
    .join('\n')

const parts = []
parts.push('/* Generated by scripts/build-client.mjs — do not edit. */')
parts.push('window.__ModuleLoader__.load({')
parts.push(`  id: ${JSON.stringify(bundleId)},`)
parts.push('  factory: (require) => {')
parts.push('    const __factories = {')
for (const [id, source] of modules) {
  parts.push(`      ${JSON.stringify(id)}: function (module, exports, __require) {`)
  parts.push(indent(source.replace(/\s+$/, '')))
  parts.push('      },')
}
parts.push('    }')
parts.push('    const __cache = Object.create(null)')
parts.push('    const __require = (id) => {')
parts.push('      const factory = __factories[id]')
parts.push('      if (factory === undefined) return require(id)')
parts.push('      const cached = __cache[id]')
parts.push('      if (cached !== undefined) return cached.exports')
parts.push('      const module = { exports: {} }')
parts.push('      __cache[id] = module')
parts.push('      factory(module, module.exports, __require)')
parts.push('      return module.exports')
parts.push('    }')
parts.push(`    return __require(${JSON.stringify(toId(entry))})`)
parts.push('  },')
parts.push('})')
parts.push('')

mkdirSync(dirname(outFile), { recursive: true })
writeFileSync(outFile, parts.join('\n'), 'utf8')

const bytes = statSync(outFile).size
console.log(`bundled ${modules.size} modules -> ${relative(root, outFile).split(sep).join('/')} (${bytes} bytes)`)
